import Foundation
import Testing
@testable import AllInOneIMECore

/// The English words the key detector knows are compiled into the core (`RedactionWordList`, generated by
/// Scripts/make-redaction-words.swift): every system has them, and on a Mac they are the system's list as it was read.
struct RedactionWordListTests {
    static var sourceIsHere: Bool { FileManager.default.fileExists(atPath: RedactionWordList.source) }

    @Test func theWordsAreInTheCore() {
        #expect(RedactionWords.english.count == RedactionWordList.count)
        #expect(RedactionWordList.letters.count == 26)
        for word in ["aardvark", "telephone", "kitchen", "zyzzogeton"] {
            #expect(RedactionWords.english.contains(word), "\(word)")
        }
        #expect(!RedactionWords.english.contains("") && !RedactionWords.english.contains("ab"))
    }

    /// Where the list came from is here (a Mac): the compiled words are exactly its lines of 3 characters or more,
    /// lowercased, as the core read /usr/share/dict/words before.
    @Test(.enabled(if: sourceIsHere)) func theWordsAreTheSystemsList() throws {
        let text = try String(contentsOfFile: RedactionWordList.source, encoding: .utf8)
        var words = Set<String>()
        for line in text.split(separator: "\n") where line.count >= 3 { words.insert(line.lowercased()) }
        #expect(RedactionWords.english == words)
        #if os(macOS)
        let system = try String(contentsOfFile: "/usr/share/dict/words", encoding: .utf8)
        #expect(system == text, "/usr/share/dict/words is web2")
        #endif
    }
}
